import{_ as p,a0 as o,w as d,s as h,I as t,x as i,a1 as a,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用统一阻止列表和白名单来更新主机文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用统一阻止列表和白名单来更新主机文件 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用统一阻止列表和白名单来更新主机文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用统一阻止列表和白名单来更新主机文件 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting","title":"使用统一阻止列表和白名单来更新主机文件","tag":"201707","desc":""},"relativePath":"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting.md","filePath":"[post].md"}'),r={name:"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting.md"};function g(k,s,u,b,c,f){const e=o("Link");return d(),h("div",null,[s[19]||(s[19]=t("h1",{id:"使用统一阻止列表和白名单来更新主机文件",tabindex:"-1"},[i("使用统一阻止列表和白名单来更新主机文件 "),t("a",{class:"header-anchor",href:"#使用统一阻止列表和白名单来更新主机文件","aria-label":"Permalink to “使用统一阻止列表和白名单来更新主机文件”"},"​")],-1)),s[20]||(s[20]=t("p",null,[t("img",{src:"https://irp-cdn.multiscreensite.com/58a25abc/dms3rep/multi/desktop/host-400x300.jpg",alt:""})],-1)),s[21]||(s[21]=t("p",null,"网上有许多持续维护的含有不同垃圾域的有用列表。将这些列表复制到你的主机文件中可以轻松阻止大量的域，你的系统将根本不用去连接它们。此方法可以在不安装浏览器插件的情况下工作，并且将为系统上任何浏览器（和任何其他程序）提供阻止操作。",-1)),t("p",null,[s[1]||(s[1]=i("在本教程中，我将向你展示如何在 Linux 中启动并运行 Steven Black 的",-1)),a(e,{href:"https://github.com/StevenBlack/hosts"},{default:n(()=>[...s[0]||(s[0]=[i("统一主机脚本",-1)])]),_:1}),s[2]||(s[2]=i("。该脚本将使用来自多个来源的最新已知的广告服务器、网络钓鱼网站和其他网络垃圾的地址来更新你的计算机主机文件，同时提供一个漂亮、干净的方式来管理你自己的黑名单/白名单，其分别来自于该脚本管理的各个列表。",-1))]),s[22]||(s[22]=l(`<p>在将 30,000 个域放入主机文件之前，需要注意两点。首先，这些巨大的列表包含可能需要解除封锁的服务器，以便进行在线购买或其他一些临时情况。如果你弄乱了你的主机文件，你要知道网上的某些东西可能会出现问题。为了解决这个问题，我将向你展示如何使用方便的打开/关闭开关，以便你可以快速禁用你的阻止列表来购买喜马拉雅盐雾灯（它是等离子灯）。我仍然认为这些列表的目的之一是将所有的一切都封锁（有点烦人，直到我想到了做一个关闭开关）。如果你经常遇到你需要的服务器被阻止的问题，只需将其添加到白名单文件中即可。</p><p>第二个问题是性能受到了轻微的影响, 因为每次调用一个域时, 系统都必须检查整个列表。只是有一点点影响, 而没有大到让我因此而放弃黑名单，让每一个连接都通过。你具体要怎么选择自己看着办。</p><p>主机文件通过将请求定向到 127.0.0.1 或 0.0.0.0（换句话说定向到空地址）来阻止请求。有人说使用 0.0.0.0 是更快，问题更少的方法。你可以将脚本配置为使用 <code>-ip nnn.nnn.nnn.nnn</code> 这样的 ip 选项来作为阻止 ip，但默认值是 0.0.0.0，这是我使用的值。</p><p>我曾经将 Steven Black 的脚本做的事每隔一段时间就手动做一遍，进到每一个站点，将他们的列表拷贝/粘贴到我的主机文件中，做一个查找替换将其中的 127 变成 0 等等。我知道整件事情可以自动化，这样做有点傻，但我从来没有花时间解决这个问题。直到我找到这个脚本，现在这事已经是一个被遗忘的杂务。</p><p>让我们先下载一份最新的 Steven Black 的代码拷贝（大约 150MB），以便我们可以进行下一步。你需要安装 git，因此如果还没安装，进入到终端输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git</span></span></code></pre></div><p>安装完之后，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir unifiedhosts </span></span>
<span class="line"><span>cd unifiedhosts</span></span>
<span class="line"><span>git clone https://github.com/StevenBlack/hosts.git</span></span>
<span class="line"><span>cd hosts</span></span></code></pre></div>`,8)),t("p",null,[s[4]||(s[4]=i("当你打开了 Steven 的脚本时，让我们来看看有什么选项。该脚本有几个选项和扩展，但扩展我不会在这里提交，但如果你到了这一步并且你有兴趣，",-1)),a(e,{href:"https://github.com/StevenBlack/hosts/blob/master/readme.md"},{default:n(()=>[...s[3]||(s[3]=[i("readme.md",-1)])]),_:1}),s[5]||(s[5]=i(" 可以告诉你所有你需要知道的。",-1))]),s[23]||(s[23]=l(`<p>你需要安装 python 来运行此脚本，并且与版本有关。要找到你安装的 Python 版本，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python --version</span></span></code></pre></div><p>如果你还没安装 Python:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install python</span></span></code></pre></div><p>对于 Python 2.7，如下所示，输入 <code>python</code> 来执行脚本。对于 Python 3，在命令中的 <code>python</code> 替换成 <code>python3</code>。执行后，该脚本会确保它具有每个列表的最新版本，如果没有，它会抓取一个新的副本。然后，它会写入一个新的主机文件，包括了你的黑名单/白名单中的任何内容。让我们尝试使用 <code>-r</code> 选项来替换我们的当前的主机文件，而 <code>-a</code> 选项可以脚本不会问我们任何问题。回到终端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python updateHostsFile.py -r -a</span></span></code></pre></div><p>该命令将询问你的 root 密码，以便能够写入 <code>/etc/</code>。为了使新更新的列表处于激活状态，某些系统需要清除 DNS 缓存。在同一个硬件设备上，我观察到不同的操作系统表现出非常不同的行为，在没有刷新缓存的情况下不同的服务器变为可访问/不可访问所需的时间长度都不同。我已经看到了从即时更新（Slackware）到重启更新（Windows）的各种情况。有一些命令可以刷新 DNS 缓存，但是它们在每个操作系统甚至每个发行版上都不同，所以如果没有生效，只需要重新启动就行了。</p><p>现在，只要将你的个人例外添加到黑名单/白名单中，并且只要你想要更新主机文件，运行该脚本就好。该脚本将根据你的要求调整生成的主机文件，每次运行文件时会自动追加你额外的列表。</p><p>最后，我们来创建一个打开/关闭开关，对于打开和关闭功能每个都创建一个脚本，所以回到终端输入下面的内容创建关闭开关（用你自己的文本编辑器替换 leafpad）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>leafpad hosts-off.sh</span></span></code></pre></div><p>在新文件中输入下面的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>sudo mv /etc/hosts /etc/hostsDISABLED</span></span></code></pre></div><p>接着让它可执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x hosts-off.sh</span></span></code></pre></div><p>相似地，对于打开开关：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>leafpad hosts-on.sh</span></span></code></pre></div><p>在新文件中输入下面的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>sudo mv /etc/hostsDISABLED /etc/hosts</span></span></code></pre></div><p>最后让它可执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x hosts-on.sh</span></span></code></pre></div><p>你所需要做的是为每个脚本创建一个快捷方式，标记为 HOSTS-ON 和 HOSTS-OFF，放在你能找到它们的地方。</p><hr>`,22)),t("p",null,[s[7]||(s[7]=i("via: ",-1)),a(e,{href:"https://www.darrentoback.com/this-script-updates-hosts-files-using-a-multi-source-unified-block-list-with-whitelisting"},{default:n(()=>[...s[6]||(s[6]=[i("https://www.darrentoback.com/this-script-updates-hosts-files-using-a-multi-source-unified-block-list-with-whitelisting",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=i("作者：",-1)),a(e,{href:"https://www.darrentoback.com/about-me"},{default:n(()=>[...s[8]||(s[8]=[i("dmt",-1)])]),_:1}),s[12]||(s[12]=i(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[9]||(s[9]=[i("geekpi",-1)])]),_:1}),s[13]||(s[13]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[i("Linux中国",-1)])]),_:1}),s[18]||(s[18]=i(" 荣誉推出",-1))])])}const v=p(r,[["render",g]]);export{C as __pageData,v as default};
